//! Authored source/semantic judgments, no provider, gold or storage claims.
use lightog_core::{common::{canonical_hash as hash,text_sha},knowledge_build,semantic_review_v2 as review,source_learning_v1 as learning,source_support_gap_v2,support_selection};
use serde_json::{json,Value};

fn fixture()->Value{
    let text="🚀 Mode Alpha.\nIt leaves the index unchanged.\nIt refers to mode Alpha.\nIf the same file is unstaged, abort.\n";let digest=text_sha(text);let size=text.encode_utf16().count();
    let snapshot=json!({"base_ref":"source_learning_authored","source_epoch":0,"graph_revision":null,"sources":[{"source_ref":"src","source_revision":"r1","original_sha256":digest,"text_sha256":digest,"parser_version":"authored/1"}]});
    let mut at=0;let fragments:Vec<_>=text.split_inclusive('\n').zip(["mode","assertion","antecedent","condition"]).map(|(quote,id)|{let start=at;at+=quote.encode_utf16().count();json!({"id":id,"origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"r1","block_ref":"b","text_sha256":digest,"span":{"start":start,"end":at,"quote":quote,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"})}).collect();
    let es=json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"es","snapshot":snapshot,"fragments":fragments});
    let context=json!({"examples":{"es":es},"source_texts":[{"source_ref":"src","source_revision":"r1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"b","start":0,"end":size}]}],"authority":{"requests":[],"allowed_snapshots":[snapshot],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});
    let question="How does mode Alpha affect the index?";
    let runtime=json!({"current_snapshot":snapshot,"grants":[{"request_ref":"request_authored","question_sha256":text_sha(question),"base_ref":snapshot["base_ref"],"source_epoch":0,"access_mode":"LEARN","learning_requested":true}],"persisted_job_sha256":null,"persisted_revision":0,"support_hold_candidate_sha256":[],"graph_record_sha256":null,"commit_record_sha256":null,"index_record_sha256":null,"index_payload_sha256":null});
    json!({"contract_version":learning::VERSION,"request":{"request_ref":"request_authored","raw_question":question,"cq_seeds":[{"seed_id":"seed_authored","text":question}],"kind":"DISCOVERY","policy_version":"authored-policy/1"},"evidence_set":es,"source_gap":null,"context":context,"runtime":runtime})
}
fn gate(f:&Value,unit:&str)->Value{
    let es=&f["evidence_set"];let context=&f["context"];let prepared=knowledge_build::prepare_extract(&json!({"evidence_set_ref":es["evidence_set_id"],"cq_guidance":f["request"]["raw_question"],"trusted_context":context})).unwrap();
    let raw=json!({"entities":[{"local_id":"Alpha","surface":"Alpha","type_label":null,"mention_evidence_id":"mode"}],"candidates":[{"kind":"ATTRIBUTE","subject_local_id":"Alpha","predicate":{"label":"index effect","description":"Effect on index state","evidence_ids":["assertion"]},"object":{"entity_local_id":null,"typed_value":{"kind":"STRING","value":"unchanged"}},"direction":"NONE","description":"Mode Alpha leaves the index unchanged.","keywords":["index"],"qualifiers":{"scope":"Mode Alpha","modality":"REPORTED","negated":false,"unit":null,"effective_time":null},"conditions":[],"support_roles":{"assertion":["assertion"],"subject_scope":["mode"],"antecedent":["antecedent"],"condition":[]}}]});
    let m=support_selection::execute("materialize",&json!({"prepared":prepared,"trusted_context":context,"raw":raw,"unit_id":unit,"max_candidates":8})).unwrap();assert_eq!(m["candidates"].as_array().unwrap().len(),1);
    let mut q=json!({"contract_version":review::VERSION,"candidates":m["candidates"],"prepared":prepared,"trusted_context":context,"receipts":m["receipts"],"context_evidence_ids":["mode","assertion","antecedent","condition"],"max_context_utf16":12000});q["manifest"]=review::execute("prepare",&q).unwrap()["manifest"].clone();
    let dimensions:serde_json::Map<_,_>=review::DIMENSIONS.iter().map(|d|(d.to_string(),json!({"decision":if *d=="units"{"NOT_APPLICABLE"}else{"SUPPORTED"},"reason":"Authored independent synthetic judgment, not certified world truth.","evidence_ids":["assertion","mode","antecedent"]}))).collect();q["review_output"]=json!({"reviews":[{"candidate_id":q["candidates"][0]["candidate_id"],"decision":"SUPPORTED","dimensions":dimensions}]});q["review_provenance"]=json!({"origin":"SYNTHETIC","review_request_id":format!("review_{unit}"),"proposal_request_ids":[format!("proposal_{unit}")],"review_output_sha256":hash(&q["review_output"]),"model":"synthetic-offline","config_revision":1});q
}
fn payload(f:&Value,j:&Value)->Value{let mut runtime=f["runtime"].clone();runtime["persisted_job_sha256"]=j["job_sha256"].clone();runtime["persisted_revision"]=j["revision"].clone();json!({"contract_version":learning::VERSION,"job":j,"context":f["context"],"runtime":runtime})}
fn job(f:&Value)->Value{learning::execute("create",f).unwrap()["job"].clone()}
fn validating(f:&Value)->Value{let mut j=job(f);for stage in ["RETRIEVING","EXTRACTING","VALIDATING"]{let mut p=payload(f,&j);p["next_stage"]=json!(stage);j=learning::execute("step",&p).unwrap()["job"].clone();}j}
fn prepare(f:&Value,j:&Value,base:Value,unit:&str)->Value{let mut p=payload(f,j);p["gate_input"]=gate(f,unit);p["base_graph"]=base.clone();if !base.is_null(){p["runtime"]["graph_record_sha256"]=json!(hash(&base));}learning::execute("prepare_commit",&p).unwrap()}
fn receipt(plan:&Value)->Value{json!({"contract_version":learning::COMMIT_VERSION,"receipt_ref":"actual_host_receipt_authored","task_ref":plan["task_ref"],"idempotency_key":plan["idempotency_key"],"commit_plan_sha256":plan["plan_sha256"],"input_snapshot_sha256":plan["input_snapshot_sha256"],"base_graph_digest":plan["base_graph_digest"],"output_graph_revision":plan["output_graph_revision"],"output_graph_digest":plan["output_graph_digest"],"write_set_sha256":plan["write_set_sha256"],"index_state":"PENDING"})}
fn commit(f:&Value,prepared:&Value)->(Value,Value){let r=receipt(&prepared["commit_plan"]);let mut p=payload(f,&prepared["job"]);p["commit_plan"]=prepared["commit_plan"].clone();p["persisted_write_set"]=prepared["write_set"].clone();p["receipt"]=r.clone();p["runtime"]["graph_record_sha256"]=json!(hash(&prepared["write_set"]));p["runtime"]["commit_record_sha256"]=json!(hash(&r));let j=learning::execute("confirm_commit",&p).unwrap()["job"].clone();(j,r)}
fn read_context(f:&Value,bundle:&Value)->Value{let mut context=f["context"].clone();context["authority"]["allowed_snapshots"]=json!([bundle["read_snapshot"]]);context}
fn projection(f:&Value,bundle:&Value)->Value{let mut runtime=f["runtime"].clone();runtime["current_snapshot"]=bundle["read_snapshot"].clone();runtime["graph_record_sha256"]=json!(hash(bundle));learning::execute("project_read",&json!({"contract_version":learning::VERSION,"write_set":bundle,"read_snapshot":bundle["read_snapshot"],"context":read_context(f,bundle),"runtime":runtime})).unwrap()}
fn lexical_payload(projection:&Value)->Value{let mut records=vec![];let mut seen=std::collections::BTreeSet::new();for es in projection["evidence_sets"].as_array().unwrap(){for f in es["fragments"].as_array().unwrap(){if seen.insert(f["id"].as_str().unwrap()){records.push(json!({"id":format!("doc:{}",f["id"].as_str().unwrap()),"kind":"DOCUMENT","text":f["span"]["quote"],"entity_refs":[],"evidence_ids":[f["id"]],"status":"SOURCE","profile":null,"embedding":null}));}}}let mut owner=std::collections::BTreeMap::new();for p in projection["p2Build"]["profiles"].as_array().unwrap(){let id=format!("profile:{}",p["id"].as_str().unwrap());owner.insert(p["owner_id"].as_str().unwrap(),id.clone());let ids:Vec<_>=p["evidence_refs"].as_array().unwrap().iter().map(|r|r["evidence_id"].clone()).collect();records.push(json!({"id":id,"kind":if p["kind"]=="ATTRIBUTE"{"RELATION"}else{p["kind"].as_str().unwrap()},"text":p["text"],"entity_refs":p["entity_refs"],"evidence_ids":ids,"status":"DISCOVERY_HINT","profile":null,"embedding":null}));}let mut edges=vec![];for s in projection["p2Build"]["graph"]["statements"].as_array().unwrap(){let ids:Vec<_>=s["evidence_refs"].as_array().unwrap().iter().map(|r|r["evidence_id"].clone()).collect();edges.push(json!({"id":format!("edge:{}:{}",s["id"].as_str().unwrap(),s["subject_id"].as_str().unwrap()),"source_record_id":owner[s["id"].as_str().unwrap()],"target_record_id":owner[s["subject_id"].as_str().unwrap()],"evidence_ids":ids,"status":"DISCOVERY_HINT"}));}json!({"contract_version":"lightog-hybrid-retrieval/0.1","question":"index behavior","queries":{"document":"index behavior","entity":"Alpha","relation":"index effect"},"snapshot":projection["snapshot"],"trusted_index":{"records":records,"edges":edges,"manifests":[],"context":projection["context"],"evidence_token_counts":{},"tokenizer":null},"query_vectors":[],"rerank":null,"options":{"channel_top_k":20,"result_top_k":12,"rrf_k":60,"max_graph_neighbors":12,"max_context_utf16":16000,"max_context_tokens":null,"min_cosine":0.0}})}
fn dense_payload(p:&mut Value){let space=json!({"provider":"authored-synthetic","model":"authored-vector-model","model_revision":"fixture/1","dimensions":2,"normalization":"NONE","distance":"COSINE","text_policy":"raw/1","tokenizer_version":"fixture/1"});for component in ["CHUNK","ENTITY","RELATION"]{let indices:Vec<_>=p["trusted_index"]["records"].as_array().unwrap().iter().enumerate().filter(|(_,r)|if component=="CHUNK"{r["kind"]=="DOCUMENT"}else{r["kind"]==component}).map(|(i,_)|i).collect();if indices.is_empty(){continue;}let index_id=format!("idx_{component}");let n=indices.len();let manifest=json!({"contract_version":"lightog-knowledge/0.2","index_id":index_id,"index_revision":"fixture1","component":component,"snapshot":p["snapshot"],"vector_space":space,"status":"ACTIVE","records_total":n,"vectors_completed":n,"build_receipt_ref":format!("build_{index_id}")});let r=json!({"receipt_ref":manifest["build_receipt_ref"],"kind":"INDEX_BUILD","status":"COMPLETE","index_id":index_id,"index_revision":"fixture1","component":component,"snapshot_sha256":lightog_demand::wire::sha(&p["snapshot"]).unwrap(),"vector_space_sha256":lightog_demand::wire::sha(&space).unwrap(),"records_total":n,"vectors_completed":n});p["trusted_index"]["context"]["authority"]["receipts"].as_array_mut().unwrap().push(r);if !p["trusted_index"]["context"]["authority"]["active_indexes"].is_array(){p["trusted_index"]["context"]["authority"]["active_indexes"]=json!([]);}p["trusted_index"]["context"]["authority"]["active_indexes"].as_array_mut().unwrap().push(manifest.clone());p["trusted_index"]["manifests"].as_array_mut().unwrap().push(manifest);for i in indices{p["trusted_index"]["records"][i]["embedding"]=json!({"index_id":index_id,"values":[1.0,0.5],"text_sha256":text_sha(p["trusted_index"]["records"][i]["text"].as_str().unwrap())});}}}

#[test]fn raw_cq_null_spec_discovery_needs_no_parent_and_is_deterministic(){let f=fixture();let j=job(&f);assert_eq!(j["question_spec"],Value::Null);assert_eq!(j["source_gap_binding"],Value::Null);assert_eq!(j["stage"],"QUEUED");assert_eq!(j,job(&f));assert_eq!(j["task_ref"],format!("sl_{}",&j["idempotency_key"].as_str().unwrap()[..32]));}
#[test]fn support_closure_reuses_v2_task_validation_and_parent_hash_cannot_change(){let mut f=fixture();let mut g=gate(&f,"support_parent_authored");g["review_output"]["reviews"][0]["decision"]=json!("PARTIAL");g["review_output"]["reviews"][0]["dimensions"]["scope"]["decision"]=json!("PARTIAL");g["review_provenance"]["review_output_sha256"]=json!(hash(&g["review_output"]));let judged=review::execute("apply",&g).unwrap();let empty=knowledge_build::build(&json!({"candidates":[],"snapshot":f["evidence_set"]["snapshot"],"trusted_context":f["context"]})).unwrap();let source=&f["context"]["source_texts"][0];let artifact=json!({"source_id":"src","source_sha256":f["evidence_set"]["snapshot"]["sources"][0]["text_sha256"],"snapshot":f["evidence_set"]["snapshot"],"evidenceSet":f["evidence_set"],"context":f["context"],"p2Build":empty,"all_proposal_candidates":g["candidates"],"semantic_batches":[{"unit_id":"support_parent_authored","result":{"gate_input":g,"gate_result":judged,"proposal_materialized":{"candidates":g["candidates"]},"eligible_candidates":judged["eligible_candidates"]}}],"segment_evidence_set_refs":["es"]});let prepared=source_support_gap_v2::execute("prepare",&json!({"contract_version":source_support_gap_v2::VERSION,"source":{"id":"src","content":source["text"],"sha256":f["evidence_set"]["snapshot"]["sources"][0]["text_sha256"],"original_sha256":source["original_sha256"],"parser_version":source["parser_version"],"source_revision":"r1"},"artifact":artifact,"cq_seeds":f["request"]["cq_seeds"]})).unwrap();f["request"]["kind"]=json!("SUPPORT_CLOSURE");f["source_gap"]=json!({"task":prepared["task"],"artifact":prepared["sourceArtifact"]});let created=job(&f);assert_eq!(created["intent_kind"],"SOURCE_FACT_SUPPORT");assert!(created["question_spec"].is_null());f["source_gap"]["task"]["source_fact_sha256"]=json!("0".repeat(64));assert!(learning::execute("create",&f).is_err());}
#[test]fn model_or_request_cannot_authorize_itself_or_borrow_epoch(){let f=fixture();for mode in 0..5{let mut bad=f.clone();match mode{0=>bad["runtime"]["grants"][0]["access_mode"]=json!("QUERY"),1=>bad["runtime"]["grants"][0]["learning_requested"]=json!(false),2=>bad["request"]["raw_question"]=json!("Different question"),3=>bad["runtime"]["grants"][0]["source_epoch"]=json!(3),_=>bad["request"]["approved"]=json!(true)}assert!(learning::execute("create",&bad).is_err());}}
#[test]fn cas_identity_and_source_drift_fail_but_withdrawn_job_can_stop(){let f=fixture();let j=job(&f);let mut p=payload(&f,&j);p["next_stage"]=json!("RETRIEVING");p["runtime"]["persisted_revision"]=json!(99);assert_eq!(learning::execute("step",&p).unwrap_err().code,"SOURCE_LEARNING_CAS_MISMATCH");p=payload(&f,&j);p["next_stage"]=json!("RETRIEVING");p["runtime"]["current_snapshot"]["source_epoch"]=json!(1);assert_eq!(learning::execute("step",&p).unwrap_err().code,"SOURCE_LEARNING_SOURCE_STALE");p["next_stage"]=json!("SUPERSEDED");p["context"]["source_texts"]=json!([]);p["context"]["authority"]["allowed_snapshots"]=json!([]);assert_eq!(learning::execute("step",&p).unwrap()["job"]["stage"],"SUPERSEDED");}
#[test]fn started_and_unknown_outcome_survive_serialization_and_forbid_new_phase(){let f=fixture();let mut p=payload(&f,&job(&f));p["next_stage"]=json!("RETRIEVING");let j=learning::execute("step",&p).unwrap()["job"].clone();p=payload(&f,&j);p["attempt_id"]=json!("first");p["phase"]=json!("extract1");p["request_sha256"]=json!("b".repeat(64));let started=learning::execute("begin_attempt",&p).unwrap()["job"].clone();let j:Value=serde_json::from_slice(&serde_json::to_vec(&started).unwrap()).unwrap();p=payload(&f,&j);p["attempt_id"]=json!("second");p["phase"]=json!("another_phase");p["request_sha256"]=json!("c".repeat(64));assert_eq!(learning::execute("begin_attempt",&p).unwrap_err().code,"SOURCE_LEARNING_UNKNOWN_PROVIDER_NO_RETRY");p=payload(&f,&j);p["attempt_id"]=json!("first");p["outcome"]=json!("UNKNOWN");p["request_id"]=Value::Null;p["response_sha256"]=Value::Null;let unknown=learning::execute("finish_attempt",&p).unwrap()["job"].clone();p=payload(&f,&unknown);p["next_stage"]=json!("EXTRACTING");assert_eq!(learning::execute("step",&p).unwrap_err().code,"SOURCE_LEARNING_UNKNOWN_PROVIDER_NO_RETRY");}
#[test]fn commit_requires_replayed_gate_no_hold_and_actual_record_readbacks(){let f=fixture();let j=validating(&f);let mut p=payload(&f,&j);p["gate_input"]=gate(&f,"commit_authored");p["base_graph"]=Value::Null;let candidate_hash=hash(&p["gate_input"]["candidates"][0]);p["runtime"]["support_hold_candidate_sha256"]=json!([candidate_hash]);assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_KNOWN_SUPPORT_HOLD");p["runtime"]["support_hold_candidate_sha256"]=json!([]);let prepared=learning::execute("prepare_commit",&p).unwrap();let mut bad=payload(&f,&prepared["job"]);bad["commit_plan"]=prepared["commit_plan"].clone();bad["persisted_write_set"]=prepared["write_set"].clone();bad["receipt"]=receipt(&prepared["commit_plan"]);assert_eq!(learning::execute("confirm_commit",&bad).unwrap_err().code,"SOURCE_LEARNING_GRAPH_NOT_PERSISTED");let (pending,_)=commit(&f,&prepared);assert_eq!(pending["stage"],"INDEX_PENDING");assert!(pending["index_ack"].is_null());}
#[test]fn published_read_snapshot_is_explicit_projection_not_archive_rewrite(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"projection_authored");let bundle=&prepared["write_set"];let original=bundle["builds"][0]["graph"].clone();let projected=projection(&f,bundle);assert_eq!(bundle["builds"][0]["graph"],original);assert_eq!(original["snapshot"]["graph_revision"],Value::Null);assert_eq!(projected["snapshot"]["graph_revision"],bundle["output_graph_revision"]);for p in projected["p2Build"]["profiles"].as_array().unwrap(){assert_eq!(p["snapshot"],projected["snapshot"]);assert_eq!(p["status"],"DISCOVERY_HINT");}assert_eq!(projected["projection_receipt"]["identity_merge_policy"],"EXACT_OWNER_ID_ONLY_NOT_NAMES");assert_eq!(projected["p2Build"]["graph"]["status"],"DERIVED_NAVIGATION_NOT_CANDIDATE_ARCHIVE");}
#[test]fn same_source_increment_preserves_each_build_snapshot_and_reprojects_current_read_version(){let f=fixture();let first=prepare(&f,&validating(&f),Value::Null,"increment_first");let original=first["write_set"]["builds"][0].clone();let mut next=f.clone();next["evidence_set"]["snapshot"]=first["write_set"]["read_snapshot"].clone();next["context"]["examples"]["es"]=next["evidence_set"].clone();next["context"]["authority"]["allowed_snapshots"]=json!([next["evidence_set"]["snapshot"]]);next["runtime"]["current_snapshot"]=next["evidence_set"]["snapshot"].clone();next["request"]["raw_question"]=json!("Discover another index behavior detail.");next["runtime"]["grants"][0]["question_sha256"]=json!(text_sha(next["request"]["raw_question"].as_str().unwrap()));let second=prepare(&next,&validating(&next),first["write_set"].clone(),"increment_second");assert_eq!(second["write_set"]["builds"].as_array().unwrap().len(),2);assert_eq!(second["write_set"]["builds"][0],original);assert_eq!(second["write_set"]["builds"][1]["graph"]["snapshot"],first["write_set"]["read_snapshot"]);let read=projection(&next,&second["write_set"]);assert_ne!(read["snapshot"]["graph_revision"],first["write_set"]["output_graph_revision"]);for p in read["p2Build"]["profiles"].as_array().unwrap(){assert_eq!(p["snapshot"],read["snapshot"]);}let mut stale=next.clone();stale["runtime"]["current_snapshot"]["source_epoch"]=json!(9);let mut p=payload(&stale,&validating(&next));p["base_graph"]=first["write_set"].clone();p["gate_input"]=gate(&next,"stale_increment");p["runtime"]["graph_record_sha256"]=json!(hash(&first["write_set"]));assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_SOURCE_STALE");}
#[test]fn lexical_index_requires_real_payload_validation_and_ack_replay_before_completed(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"index_authored");let bundle=&prepared["write_set"];let (pending,receipt)=commit(&f,&prepared);let projected=projection(&f,bundle);let validation=lexical_payload(&projected);let mut p=payload(&f,&pending);p["context"]=read_context(&f,bundle);p["runtime"]["current_snapshot"]=bundle["read_snapshot"].clone();p["runtime"]["graph_record_sha256"]=json!(hash(bundle));p["runtime"]["commit_record_sha256"]=json!(hash(&receipt));p["runtime"]["index_payload_sha256"]=json!(hash(&validation["trusted_index"]));p["receipt"]=receipt.clone();p["write_set"]=bundle.clone();p["index_ref"]=json!("actual_index_authored");p["validation_payload"]=validation;let ready=learning::execute("prepare_index",&p).unwrap();assert_eq!(ready["index_ack"]["mode"],"LEXICAL");assert_eq!(ready["index_ack"]["vectors_completed"],0);p.as_object_mut().unwrap().remove("index_ref");p["index_ack"]=ready["index_ack"].clone();p["projection_receipt"]=ready["projection_receipt"].clone();p["runtime"]["index_record_sha256"]=json!(hash(&ready["index_ack"]));let completed=learning::execute("confirm_index",&p).unwrap();assert_eq!(completed["job"]["stage"],"COMPLETED");let mut forged=p.clone();forged["index_ack"]["records_total"]=json!(999);forged["runtime"]["index_record_sha256"]=json!(hash(&forged["index_ack"]));assert_eq!(learning::execute("confirm_index",&forged).unwrap_err().code,"SOURCE_LEARNING_INDEX_ACK_REPLAY_CHANGED");let mut missing=p;missing["validation_payload"]["trusted_index"]["records"].as_array_mut().unwrap().pop();missing["runtime"]["index_payload_sha256"]=json!(hash(&missing["validation_payload"]["trusted_index"]));assert_eq!(learning::execute("confirm_index",&missing).unwrap_err().code,"SOURCE_LEARNING_INDEX_RECORDS_CHANGED");}
#[test]fn embedding_ready_requires_each_actual_vector_matching_text_space_and_manifest(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"dense_index_authored");let bundle=&prepared["write_set"];let (pending,r)=commit(&f,&prepared);let projection=projection(&f,bundle);let mut validation=lexical_payload(&projection);dense_payload(&mut validation);let mut p=payload(&f,&pending);p["context"]=read_context(&f,bundle);p["runtime"]["current_snapshot"]=bundle["read_snapshot"].clone();p["runtime"]["graph_record_sha256"]=json!(hash(bundle));p["runtime"]["commit_record_sha256"]=json!(hash(&r));p["runtime"]["index_payload_sha256"]=json!(hash(&validation["trusted_index"]));p["receipt"]=r;p["write_set"]=bundle.clone();p["index_ref"]=json!("actual_dense_fixture");p["validation_payload"]=validation;let ack=learning::execute("prepare_index",&p).unwrap()["index_ack"].clone();assert_eq!(ack["mode"],"EMBEDDING");assert_eq!(ack["vectors_completed"],ack["records_total"]);for mode in 0..3{let mut bad=p.clone();match mode{0=>bad["validation_payload"]["trusted_index"]["records"][0]["embedding"]=Value::Null,1=>bad["validation_payload"]["trusted_index"]["records"][0]["embedding"]["values"]=json!([1.0]),_=>bad["validation_payload"]["trusted_index"]["records"][0]["embedding"]["text_sha256"]=json!("0".repeat(64))}bad["runtime"]["index_payload_sha256"]=json!(hash(&bad["validation_payload"]["trusted_index"]));assert!(learning::execute("prepare_index",&bad).is_err());}}
#[test]fn index_pending_provider_attempts_bind_new_read_revision_and_unknown_blocks_ready(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"index_attempt_authored");let bundle=&prepared["write_set"];let (pending,_)=commit(&f,&prepared);let mut p=payload(&f,&pending);p["context"]=read_context(&f,bundle);p["runtime"]["current_snapshot"]=bundle["read_snapshot"].clone();p["attempt_id"]=json!("idx_attempt1");p["phase"]=json!("EXTRACT_NOT_INDEX");p["request_sha256"]=json!("d".repeat(64));assert_eq!(learning::execute("begin_attempt",&p).unwrap_err().code,"SOURCE_LEARNING_INDEX_ATTEMPT_BINDING_INVALID");p["phase"]=json!("INDEX_DOCUMENT_EMBEDDING_0");let started=learning::execute("begin_attempt",&p).unwrap()["job"].clone();assert_eq!(started["snapshot"],pending["snapshot"]);assert_eq!(started["commit_receipt"],pending["commit_receipt"]);p=payload(&f,&started);p["attempt_id"]=json!("idx_attempt1");p["outcome"]=json!("UNKNOWN");p["request_id"]=Value::Null;p["response_sha256"]=Value::Null;let unknown=learning::execute("finish_attempt",&p).unwrap()["job"].clone();p=payload(&f,&unknown);p["context"]=read_context(&f,bundle);p["runtime"]["current_snapshot"]=bundle["read_snapshot"].clone();p["receipt"]=unknown["commit_receipt"].clone();p["write_set"]=bundle.clone();p["index_ref"]=json!("unknown_cannot_ready");p["validation_payload"]=json!({});assert_eq!(learning::execute("prepare_index",&p).unwrap_err().code,"SOURCE_LEARNING_UNKNOWN_PROVIDER_NO_RETRY");}
#[test]fn explicit_rebuild_requires_full_current_source_input_not_only_selected_positive_fact(){let old=fixture();let first=prepare(&old,&validating(&old),Value::Null,"rebuild_old");let mut f=fixture();f["evidence_set"]["snapshot"]["source_epoch"]=json!(1);f["runtime"]["current_snapshot"]=f["evidence_set"]["snapshot"].clone();f["runtime"]["grants"][0]["source_epoch"]=json!(1);f["context"]["examples"]["es"]=f["evidence_set"].clone();f["context"]["authority"]["allowed_snapshots"]=json!([f["evidence_set"]["snapshot"]]);let g=gate(&f,"rebuild_new");f["evidence_set"]["fragments"].as_array_mut().unwrap().pop();let j=validating(&f);let mut p=payload(&f,&j);p["base_graph"]=first["write_set"].clone();p["runtime"]["graph_record_sha256"]=json!(hash(&first["write_set"]));p["gate_input"]=g;p["rebuild_source_scope"]=json!(true);assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_REBUILD_FULL_SOURCE_INPUT_REQUIRED");}
fn whitespace_payload()->Value{let f=fixture();let mut context=f["context"].clone();let text=context["source_texts"][0]["text"].as_str().unwrap();let pos=text.find('\n').unwrap();let start=text[..pos].encode_utf16().count();let mut blank=context["examples"]["es"]["fragments"][0].clone();blank["id"]=json!("blank_only");blank["span"]=json!({"start":start,"end":start+1,"quote":"\n","offset_unit":"utf16_code_unit"});context["examples"]["es"]["fragments"].as_array_mut().unwrap().push(blank);let quote=context["examples"]["es"]["fragments"][0]["span"]["quote"].clone();json!({"contract_version":"lightog-hybrid-retrieval/0.1","question":"Alpha","queries":{"document":"Alpha","entity":"Alpha","relation":"Alpha"},"snapshot":f["evidence_set"]["snapshot"],"trusted_index":{"records":[{"id":"doc_nonempty","kind":"DOCUMENT","text":quote,"entity_refs":[],"evidence_ids":["mode"],"status":"SOURCE","profile":null,"embedding":null},{"id":"doc_blank","kind":"DOCUMENT","text":"\n","entity_refs":[],"evidence_ids":["blank_only"],"status":"SOURCE","profile":null,"embedding":null},{"id":"profile_blank_not_document","kind":"ENTITY","text":"\u{feff} \t","entity_refs":[],"evidence_ids":["mode"],"status":"DISCOVERY_HINT","profile":null,"embedding":null}],"edges":[],"manifests":[],"context":context,"evidence_token_counts":{},"tokenizer":null},"query_vectors":[],"rerank":null,"options":{"channel_top_k":20,"result_top_k":12,"rrf_k":60,"max_graph_neighbors":12,"max_context_utf16":16000,"max_context_tokens":null,"min_cosine":0.0}})}
#[test]fn index_projection_excludes_only_noncontent_document_without_editing_source_or_profiles(){let input=whitespace_payload();let out=learning::execute("project_index_payload",&json!({"contract_version":learning::VERSION,"validation_payload":input})).unwrap();assert_eq!(out["index_projection"]["policy"],"NONCONTENT_DOCUMENT_EXCLUDED");assert_eq!(out["index_projection"]["excluded_record_ids"],json!(["doc_blank"]));assert_eq!(out["validation_payload"]["trusted_index"]["records"],json!([input["trusted_index"]["records"][0],input["trusted_index"]["records"][2]]));assert_eq!(out["validation_payload"]["trusted_index"]["context"],input["trusted_index"]["context"]);assert_eq!(out["validation_payload"]["trusted_index"]["edges"],input["trusted_index"]["edges"]);let mut forbidden=json!({"contract_version":learning::VERSION,"validation_payload":input});forbidden["drop_record_ids"]=json!(["doc_nonempty"]);assert_eq!(learning::execute("project_index_payload",&forbidden).unwrap_err().code,"SOURCE_LEARNING_SHAPE_INVALID");}
#[test]fn index_projection_refuses_post_attach_or_deleting_edges_to_whitespace(){let input=whitespace_payload();for mode in 0..3{let mut changed=input.clone();match mode{0=>changed["trusted_index"]["records"][0]["embedding"]=json!({"index_id":"already_attached","values":[1.0,0.0],"text_sha256":"b".repeat(64)}),1=>changed["trusted_index"]["manifests"]=json!([{"status":"ACTIVE"}]),_=>changed["query_vectors"]=json!([{}])}assert_eq!(learning::execute("project_index_payload",&json!({"contract_version":learning::VERSION,"validation_payload":changed})).unwrap_err().code,"SOURCE_LEARNING_INDEX_PROJECTION_MUST_PRECEDE_ATTACH");}let mut with_edge=input;with_edge["trusted_index"]["edges"]=json!([{"id":"edge_to_blank","source_record_id":"doc_nonempty","target_record_id":"doc_blank","evidence_ids":["mode"],"status":"DISCOVERY_HINT"}]);assert_eq!(learning::execute("project_index_payload",&json!({"contract_version":learning::VERSION,"validation_payload":with_edge})).unwrap_err().code,"SOURCE_LEARNING_NONCONTENT_EDGE_REFERENCE");}

#[test]
fn source_update_before_first_graph_can_commit_without_a_fabricated_base() {
    let f=fixture(); let j=validating(&f); let mut p=payload(&f,&j);
    p["gate_input"]=gate(&f,"first_after_update"); p["base_graph"]=Value::Null;
    p["rebuild_source_scope"]=json!(true);
    let out=learning::execute("prepare_commit",&p).unwrap();
    assert!(out["commit_plan"]["base_graph_digest"].is_null());
    assert_eq!(out["write_set"]["builds"].as_array().unwrap().len(),1);
    let (pending,_)=commit(&f,&out); assert_eq!(pending["stage"],"INDEX_PENDING");
    p["runtime"]["graph_record_sha256"]=json!("a".repeat(64));
    assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_BASE_GRAPH_MISSING");
    p["runtime"]["graph_record_sha256"]=Value::Null;
    p["job"]["request"]["kind"]=json!("GAP_FILL");
    // Changed persisted jobs are rejected before commit, even on the empty-base path.
    assert!(learning::execute("prepare_commit",&p).is_err());
}
#[test]
fn first_graph_rebuild_still_requires_full_source_exposure() {
    let mut f=fixture(); let g=gate(&f,"first_incomplete");
    f["evidence_set"]["fragments"].as_array_mut().unwrap().pop();
    let j=validating(&f); let mut p=payload(&f,&j);
    p["gate_input"]=g; p["base_graph"]=Value::Null; p["rebuild_source_scope"]=json!(true);
    assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_REBUILD_FULL_SOURCE_INPUT_REQUIRED");
}
